SELECT question_id, question_template_id, question_type, question_title, question_description, required_yn, scored_yn, question_score, sort_order, created_by, created_at, updated_by, updated_at FROM popup_question WHERE question_template_id IN
#{templateId}
ORDER BY question_template_id, sort_order

SELECT option_id, question_id, option_value, option_text, correct_yn, sort_order, created_by, created_at, updated_by, updated_at FROM popup_option WHERE question_id IN
#{questionId}
ORDER BY question_id, sort_order

SELECT hidden_until_at AT TIME ZONE 'Asia/Seoul'
FROM user_popup_status
WHERE employee_no = #{userId}
  AND popup_id = #{popupId}

